script:
(function () {
  'use strict';
  // Credit card optimizer: one monthly budget, several cards - how to split it.
  // Each month every open card is charged interest = balance x APR / 12 (rounded to the cent).
  //   Optimized: every card gets its minimum (capped at what it owes) and the rest of the budget
  //   goes to the card with the highest APR that month (ties -> smaller balance), spilling to the
  //   next card if it clears. With fixed rates and fixed minimums this is the split that pays the
  //   least interest.
  //   Even split: the budget is shared equally across the cards still owing, but no card gets less
  //   than its minimum or more than it owes: pay each card min(owed, max(minimum, s)), with the
  //   share s found by bisection so the payments add up to the budget.
  //   Optional transfer to a new card: balances move from the highest-APR cards first (only cards
  //   above the intro APR), each transfer t plus its fee t x fee% fitting under the credit limit.
  //   A fully moved card drops out; the new card's balance is the transfers plus fees, its minimum
  //   is the greater of $25 and 2% of that balance, and its APR is the intro rate for the intro
  //   months, then the later rate.
  // Verified (scratchpad b5debt/math2.test.js):
  //   one card of $10,000 at 12% with a $222.45 budget -> 60 months, interest within $0.10 of the
  //   closed form $3,346.67 (60 x 222.4445 - 10,000), the same for both splits;
  //   even split of $300 over cards owing $1,000 / $1,000 / $50 with $25 minimums -> $125, $125,
  //   $50 (the $50 card is capped and its unused share is shared by the others);
  //   even split with minimums $200 / $25 and a $300 budget -> $200 and $100;
  //   at 0% interest both splits finish in ceil(total / budget) months;
  //   optimized interest <= even split interest across 1,000 random card sets, and total paid =
  //   balances + interest (+ fees) in every plan;
  //   transfer: $6,000 limit, 3% fee, cards $5,200 at 25.49% and $1,400 at 29.99% -> $1,400 moved
  //   (fee $42) then $4,425.24 from the 25.49% card (fee $132.76), exactly filling the limit.
  //   Default example ($700 budget): optimized 23 months and $3,081.24 interest, even split
  //   24 months and $3,340.18; with the default transfer offer 21 months and $1,327.87 incl. fees.
  var MAX_MONTHS = 1200;
  var MAX_CARDS = 8;
  var NEW_CARD_MIN_FLOOR = 25, NEW_CARD_MIN_PCT = 0.02;
  var DEFAULTS = [
    { name: 'Travel card', balance: 5200, apr: 25.49, min: 160 },
    { name: 'Store card', balance: 1400, apr: 29.99, min: 45 },
    { name: 'Cash-back card', balance: 3800, apr: 21.99, min: 115 },
    { name: 'Old bank card', balance: 2600, apr: 17.99, min: 75 }
  ];
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var monthName = new Intl.DateTimeFormat('en-US', { month: 'short', year: 'numeric' });
  var rowCounter = 0;

  // ---- Calculation ----
  function cents(x) { return Math.round(x * 100) / 100; }

  function aprAt(card, m) {
    return card.introMonths && m <= card.introMonths ? card.introApr : card.apr;
  }

  // cards: [{ name, balance, apr, min }]; offer: { limit, introApr, introMonths, apr, fee } or null.
  function applyTransfer(cards, offer) {
    var out = cards.map(function (c) { return { name: c.name, balance: c.balance, apr: c.apr, min: c.min, moved: 0 }; });
    if (!offer) return { cards: out, fee: 0, moved: 0 };
    var room = offer.limit, moved = 0, fee = 0;
    var idx = out.map(function (c, i) { return i; }).filter(function (i) { return out[i].apr > offer.introApr; });
    idx.sort(function (a, b) { return (out[b].apr - out[a].apr) || (a - b); });
    idx.forEach(function (i) {
      if (room <= 0.005) return;
      var t = Math.min(out[i].balance, Math.floor(room / (1 + offer.fee) * 100) / 100);
      if (t <= 0) return;
      var f = cents(t * offer.fee);
      out[i].balance = cents(out[i].balance - t); out[i].moved = t;
      room = cents(room - t - f); moved += t; fee += f;
    });
    var kept = out.filter(function (c) { return c.balance > 0.005; });
    if (moved > 0) {
      var nb = cents(moved + fee);
      kept.push({ name: 'New card', balance: nb, apr: offer.apr, introApr: offer.introApr, introMonths: offer.introMonths,
        min: cents(Math.min(nb, Math.max(NEW_CARD_MIN_FLOOR, nb * NEW_CARD_MIN_PCT))), isNew: true, moved: 0 });
    }
    return { cards: kept, fee: cents(fee), moved: cents(moved), detail: out };
  }

  // Even split of `budget` over owed amounts with minimums.
  function evenSplit(owed, mins, budget) {
    var total = owed.reduce(function (s, b) { return s + b; }, 0);
    if (total <= budget) return owed.slice();
    function paid(s) {
      var t = 0;
      for (var i = 0; i < owed.length; i++) if (owed[i] > 0) t += Math.min(owed[i], Math.max(mins[i], s));
      return t;
    }
    var lo = 0, hi = Math.max.apply(null, owed);
    for (var k = 0; k < 100; k++) { var mid = (lo + hi) / 2; if (paid(mid) > budget) hi = mid; else lo = mid; }
    var pays = owed.map(function (b, i) { return b > 0 ? cents(Math.min(b, Math.max(mins[i], lo))) : 0; });
    var left = cents(budget - pays.reduce(function (s, p) { return s + p; }, 0));
    for (var i = 0; i < pays.length && left > 0.005; i++) {
      var room = cents(owed[i] - pays[i]);
      if (room <= 0) continue;
      var add = Math.min(room, left);
      pays[i] = cents(pays[i] + add); left = cents(left - add);
    }
    return pays;
  }

  function optimalSplit(owed, mins, rates, budget) {
    var n = owed.length, pays = [], avail = budget, i;
    for (i = 0; i < n; i++) { pays.push(owed[i] > 0 ? Math.min(mins[i], owed[i]) : 0); avail -= pays[i]; }
    var idx = owed.map(function (b, k) { return k; }).sort(function (a, b) { return (rates[b] - rates[a]) || (owed[a] - owed[b]) || (a - b); });
    for (var k = 0; k < n && avail > 0.005; k++) {
      i = idx[k];
      var more = Math.min(avail, owed[i] - pays[i]);
      if (more > 0) { pays[i] = cents(pays[i] + more); avail -= more; }
    }
    return pays;
  }

  function simulate(cards, budget, mode) {
    var n = cards.length, bal = cards.map(function (c) { return c.balance; });
    var mins = cards.map(function (c) { return c.min; });
    var cleared = cards.map(function () { return 0; }), cardInterest = cards.map(function () { return 0; });
    var interest = 0, paid = 0, first = null;
    for (var m = 1; m <= MAX_MONTHS; m++) {
      var rates = [], i;
      for (i = 0; i < n; i++) {
        rates.push(aprAt(cards[i], m));
        if (bal[i] <= 0.005) { bal[i] = 0; continue; }
        var c = cents(bal[i] * rates[i] / 12);
        bal[i] = cents(bal[i] + c); interest += c; cardInterest[i] += c;
      }
      var pays = mode === 'even' ? evenSplit(bal, mins, budget) : optimalSplit(bal, mins, rates, budget);
      if (!first) first = pays.slice();
      var open = 0;
      for (i = 0; i < n; i++) {
        if (bal[i] <= 0) continue;
        bal[i] = cents(bal[i] - pays[i]); paid += pays[i];
        if (bal[i] <= 0.005) { bal[i] = 0; cleared[i] = m; } else open++;
      }
      if (open === 0) return { paidOff: true, months: m, interest: interest, paid: paid, cleared: cleared, cardInterest: cardInterest, first: first };
    }
    return { paidOff: false, months: MAX_MONTHS, interest: interest, paid: paid, cleared: cleared, cardInterest: cardInterest, first: first };
  }

  // ---- Page ----
  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function dateAfter(months) {
    var now = new Date();
    return monthName.format(new Date(now.getFullYear(), now.getMonth() + months, 1));
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) {
      var td = document.createElement('td');
      td.textContent = text;
      tr.appendChild(td);
    });
    body.appendChild(tr);
  }

  function el(tag, className, text) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    if (text) e.textContent = text;
    return e;
  }

  function numberField(id, label, value, affix, affixFirst, step, max) {
    var wrap = el('div');
    var lab = el('label', 'form-label', label);
    lab.setAttribute('for', id);
    var group = el('div', 'input-group');
    var input = el('input', 'min-w-0 flex-1 bg-transparent px-3 text-[15px] tabular-nums text-ink focus:outline-none');
    input.type = 'number'; input.id = id; input.min = '0'; input.step = step; input.inputMode = 'decimal';
    if (max) input.max = max;
    input.value = value === '' ? '' : String(value);
    var a = el('span', 'input-affix', affix);
    if (affixFirst) { group.appendChild(a); group.appendChild(input); } else { group.appendChild(input); group.appendChild(a); }
    wrap.appendChild(lab); wrap.appendChild(group);
    return wrap;
  }

  function addCardRow(c) {
    var list = document.getElementById('ccoCards');
    rowCounter++;
    var n = rowCounter;
    var row = el('div', 'space-y-3 rounded-xl border border-line p-4');
    row.setAttribute('data-card-row', String(n));
    var head = el('div', 'flex flex-wrap items-center justify-between gap-2');
    var title = el('p', 'text-sm font-semibold text-ink', 'Card');
    title.setAttribute('data-card-title', '');
    var remove = el('button', 'button-secondary h-9 px-3 text-sm', 'Remove');
    remove.type = 'button';
    remove.setAttribute('data-remove', '');
    remove.addEventListener('click', function () {
      if (list.querySelectorAll('[data-card-row]').length <= 1) return;
      row.remove();
      refreshRows(); update();
    });
    head.appendChild(title); head.appendChild(remove);
    row.appendChild(head);

    var nameWrap = el('div');
    var nameLabel = el('label', 'form-label', 'Name');
    nameLabel.setAttribute('for', 'ccoName' + n);
    var name = el('input', 'form-control');
    name.type = 'text'; name.id = 'ccoName' + n; name.maxLength = 40; name.autocomplete = 'off';
    name.placeholder = 'e.g. Visa card';
    name.value = c.name || '';
    nameWrap.appendChild(nameLabel); nameWrap.appendChild(name);
    row.appendChild(nameWrap);

    var pair = el('div', 'form-row form-row-2');
    pair.appendChild(numberField('ccoBal' + n, 'Balance', c.balance, '$', true, '100'));
    pair.appendChild(numberField('ccoApr' + n, 'APR', c.apr, '%', false, '0.1', '100'));
    row.appendChild(pair);
    row.appendChild(numberField('ccoMin' + n, 'Minimum payment', c.min, '$', true, '5'));
    list.appendChild(row);
    refreshRows();
  }

  function refreshRows() {
    var rows = document.getElementById('ccoCards').querySelectorAll('[data-card-row]');
    rows.forEach(function (row, i) {
      row.querySelector('[data-card-title]').textContent = 'Card ' + (i + 1);
      var rm = row.querySelector('[data-remove]');
      rm.disabled = rows.length <= 1;
      rm.setAttribute('aria-label', 'Remove card ' + (i + 1));
    });
    document.getElementById('ccoAdd').disabled = rows.length >= MAX_CARDS;
  }

  function readCards() {
    var out = [], ok = true;
    var rows = document.getElementById('ccoCards').querySelectorAll('[data-card-row]');
    rows.forEach(function (row, i) {
      var n = row.getAttribute('data-card-row');
      var name = document.getElementById('ccoName' + n).value.trim() || ('Card ' + (i + 1));
      var balEl = document.getElementById('ccoBal' + n), aprEl = document.getElementById('ccoApr' + n), minEl = document.getElementById('ccoMin' + n);
      var bal = parseFloat(balEl.value), apr = aprEl.value.trim() === '' ? 0 : parseFloat(aprEl.value), min = parseFloat(minEl.value);
      if (balEl.value.trim() === '' || bal === 0) {
        [balEl, aprEl, minEl].forEach(function (e) { e.setAttribute('aria-invalid', 'false'); });
        return;
      }
      var badBal = isNaN(bal) || bal < 0 || bal > 1e7, badApr = isNaN(apr) || apr < 0 || apr > 100, badMin = isNaN(min) || min <= 0;
      balEl.setAttribute('aria-invalid', String(badBal));
      aprEl.setAttribute('aria-invalid', String(badApr));
      minEl.setAttribute('aria-invalid', String(badMin));
      if (badBal || badApr || badMin) { ok = false; return; }
      out.push({ name: name, balance: bal, apr: apr / 100, min: min });
    });
    return { ok: ok, cards: out };
  }

  function readOffer() {
    var on = document.getElementById('ccoTransfer').checked;
    document.getElementById('ccoOfferFields').hidden = !on;
    if (!on) return { offer: null };
    var v = function (id) { var e = document.getElementById(id); return e.value.trim() === '' ? 0 : parseFloat(e.value); };
    var limit = v('ccoLimit'), intro = v('ccoIntro'), months = Math.round(v('ccoIntroMonths')), later = v('ccoLater'), fee = v('ccoFee');
    if ([limit, intro, months, later, fee].some(isNaN) || limit <= 0 || limit > 1e7 || intro < 0 || intro > 100 ||
        months < 0 || months > 60 || later < 0 || later > 100 || fee < 0 || fee > 20) {
      return { error: 'Check the new card: a credit limit above $0, rates from 0 to 100%, up to 60 intro months and a fee from 0 to 20%.' };
    }
    return { offer: { limit: limit, introApr: intro / 100, introMonths: months, apr: later / 100, fee: fee / 100 } };
  }

  function clearResults() {
    ['ccoOptInterest', 'ccoOptDate', 'ccoEvenInterest', 'ccoEvenDate', 'ccoSaved'].forEach(function (id) { set(id, '–'); });
    ['ccoOptNote', 'ccoEvenNote', 'ccoSavedNote', 'ccoTransferNote'].forEach(function (id) { set(id, ''); });
    document.getElementById('ccoTransferNote').hidden = true;
    clearBody('ccoThisMonth'); clearBody('ccoPayoff');
  }

  function aprText(apr) { return (apr * 100).toFixed(2).replace(/\.?0+$/, '') + '%'; }

  function update() {
    var error = document.getElementById('ccoError');
    var budget = parseFloat(document.getElementById('ccoBudget').value);
    var input = readCards(), offerIn = readOffer();
    var problem = '';
    if (!input.ok) problem = 'Check the highlighted cards: balances of $0 or more, APRs from 0 to 100% and minimum payments above $0.';
    else if (!input.cards.length) problem = 'Enter at least one card with a balance above $0.';
    else if (isNaN(budget) || budget <= 0) problem = 'Enter a monthly budget above $0.';
    else if (offerIn.error) problem = offerIn.error;
    var base, plan;
    if (!problem) {
      base = applyTransfer(input.cards, null);
      plan = offerIn.offer ? applyTransfer(input.cards, offerIn.offer) : base;
      var minSum = plan.cards.reduce(function (s, c) { return s + Math.min(c.min, c.balance); }, 0);
      if (budget < minSum - 0.005) problem = 'Your budget must cover at least the minimum payments: ' + money.format(minSum) + ' a month.';
    }
    var opt, even, noTransfer;
    if (!problem) {
      opt = simulate(plan.cards, budget, 'optimal');
      even = simulate(plan.cards, budget, 'even');
      if (!opt.paidOff || !even.paidOff) problem = 'This budget does not pay these cards off within 100 years. Raise the monthly budget.';
    }
    if (problem) { error.hidden = false; error.textContent = problem; clearResults(); return; }
    error.hidden = true; error.textContent = '';

    var fee = plan.fee;
    set('ccoOptInterest', money.format(opt.interest + fee));
    set('ccoOptNote', fee > 0 ? 'Includes the ' + money.format(fee) + ' transfer fee.' : 'Minimums first, the rest to the highest rate.');
    set('ccoOptDate', dateAfter(opt.months));
    set('ccoEvenInterest', money.format(even.interest + fee));
    set('ccoEvenDate', dateAfter(even.months));
    set('ccoEvenNote', 'Debt-free in ' + duration(even.months) + ' vs ' + duration(opt.months) + ' optimized.');
    var saved = Math.max(even.interest - opt.interest, 0);
    set('ccoSaved', money.format(saved));
    set('ccoSavedNote', even.months > opt.months ? 'And debt-free ' + duration(even.months - opt.months) + ' sooner.' : 'Same budget, less of it lost to interest.');

    var tn = document.getElementById('ccoTransferNote');
    tn.hidden = !offerIn.offer;
    if (offerIn.offer) {
      noTransfer = simulate(base.cards, budget, 'optimal');
      if (plan.moved <= 0) tn.textContent = 'No balance was moved: none of your cards has an APR above the new card’s intro rate.';
      else if (!noTransfer.paidOff || budget < base.cards.reduce(function (s, c) { return s + c.min; }, 0)) tn.textContent = 'Moving ' + money.format(plan.moved) + ' to the new card makes this budget work. Without it, the budget does not clear your cards.';
      else {
        var diff = noTransfer.interest - (opt.interest + fee);
        var from = plan.detail.filter(function (c) { return c.moved > 0; }).map(function (c) { return money.format(c.moved) + ' from ' + c.name; }).join(', ');
        tn.textContent = 'Moving ' + from + ' to the new card (fee ' + money.format(fee) + ') ' +
          (diff >= 0 ? 'saves ' + money.format(diff) : 'costs ' + money.format(-diff) + ' more') +
          ' compared with the optimized plan on your current cards (' + money.format(noTransfer.interest) + ' interest, debt-free ' + dateAfter(noTransfer.months) + ').';
      }
    }

    var thisMonth = clearBody('ccoThisMonth');
    plan.cards.forEach(function (c, i) {
      addRow(thisMonth, [c.name, money.format(c.balance), aprText(aprAt(c, 1)), money.format(Math.min(c.min, c.balance)),
        money.format(opt.first[i]), money.format(even.first[i])]);
    });
    var payoff = clearBody('ccoPayoff');
    plan.cards.forEach(function (c, i) {
      addRow(payoff, [c.name, dateAfter(opt.cleared[i]) + ' (month ' + opt.cleared[i] + ')', money.format(opt.cardInterest[i]),
        dateAfter(even.cleared[i]) + ' (month ' + even.cleared[i] + ')', money.format(even.cardInterest[i])]);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    DEFAULTS.forEach(addCardRow);
    var form = document.getElementById('ccoForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    document.getElementById('ccoAdd').addEventListener('click', function () {
      if (document.getElementById('ccoCards').querySelectorAll('[data-card-row]').length >= MAX_CARDS) return;
      addCardRow({ name: '', balance: '', apr: '', min: '' });
      update();
    });
    update();
  });
})();
